39	func contains(s, sub string) bool {
40		for i := 0; i+len(sub) <= len(s); i++ {
41			if s[i:i+len(sub)] == sub {
42				return true
43			}
44		}
45		return false
46	}
47	
48	func TestBrowserMovesDownAndUp(t *testing.T) {
49		b := NewBrowser(sampleResult())
50		b.SetSize(120, 30)
51		m, _ := b.Update(tea.KeyMsg{Type: tea.KeyDown})
52		b2 := m.(*Browser)
53		if b2.SelectedIndex() != 1 {
54			t.Errorf("after down: index = %d, want 1", b2.SelectedIndex())
55		}
56		m, _ = b2.Update(tea.KeyMsg{Type: tea.KeyUp})
57		b3 := m.(*Browser)
58		if b3.SelectedIndex() != 0 {
59			t.Errorf("after up: index = %d, want 0", b3.SelectedIndex())
60		}
61	}
62	
63	func TestBrowserQuitMessage(t *testing.T) {
64		b := NewBrowser(sampleResult())
65		b.SetSize(120, 30)
66		_, cmd := b.Update(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'q'}})
67		if cmd == nil {
68			t.Fatal("expected tea.Quit cmd")
69		}
70		if got, want := cmd(), tea.Quit(); got != want {
71			t.Errorf("cmd msg = %v, want %v", got, want)
72		}
