31	const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size
32	
33	func newDiffCmd(g *GlobalFlags) *cobra.Command {
34		o := &diffOpts{}
35		c := &cobra.Command{
36			Use:   "diff [module] [versionA] [versionB]",
37			Short: "Diff two versions of a Crow module",
38			Long: "Diff two versions of a module hosted in Crow.\n\n" +
39				"If module/versions are omitted, the interactive TUI launches\n" +
40				"(see picker task). With --plain, prints unified diff to stdout.",
41			Args:          cobra.MaximumNArgs(3),
42			SilenceUsage:  true,
43			SilenceErrors: true,
44			RunE: func(cmd *cobra.Command, args []string) error {
45				return runDiff(cmd.Context(), cmd, args, g, o)
46			},
47		}
48		c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
49		c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
50		c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
51		c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
52		return c
53	}
