129	// isTTY reports whether w is a *os.File backed by a terminal.
130	func isTTY(w io.Writer) bool {
131		f, ok := w.(*os.File)
132		if !ok {
133			return false
134		}
135		return term.IsTerminal(int(f.Fd()))
136	}
137	
138	// renderPlain writes the diff result to w in unified-diff format.
139	// "no differences" is emitted when there are zero files in the result.
140	func renderPlain(w io.Writer, r diff.Result) error {
141		if len(r.Files) == 0 {
142			_, err := fmt.Fprintln(w, "no differences")
143			return err
144		}
145		for i, fd := range r.Files {
146			if i > 0 {
147				_, _ = fmt.Fprintln(w)
148			}
149			_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
150			_, _ = fmt.Fprint(w, fd.Unified)
151		}
152		return nil
153	}
